-- StreamSnow admin bootstrap: one-time Snowflake objects for a first deploy.
-- Generated from streamsnow.config.yaml (container runtime, stage-copy deploy source).
-- Review every statement, then run it once as an account admin (Snowsight
-- worksheet, or `snow sql --stdin` on an admin connection). Re-runnable except
-- the external access integration statement (see section 4).
-- Deployed apps run with owner's rights: queries execute as the CI role that
-- deploys them, and viewers need only USAGE on each app.

-- 1. Objects ------------------------------------------------------------
USE ROLE SYSADMIN;
CREATE DATABASE IF NOT EXISTS STREAMSNOW_APPS;
CREATE SCHEMA IF NOT EXISTS STREAMSNOW_APPS.DASHBOARDS;
CREATE WAREHOUSE IF NOT EXISTS STREAMSNOW_WH
  WAREHOUSE_SIZE = XSMALL AUTO_SUSPEND = 60 AUTO_RESUME = TRUE
  INITIALLY_SUSPENDED = TRUE;

-- 2. Roles and the CI service user ----------------------------------------
USE ROLE USERADMIN;
CREATE ROLE IF NOT EXISTS STREAMSNOW_DEPLOY_ROLE;  -- deploys and owns the apps (CI)
CREATE ROLE IF NOT EXISTS STREAMSNOW_VIEWER_ROLE;  -- opens the apps (no data grants by default)
-- Key-pair auth (no password): generate a key pair, paste the PUBLIC key
-- below, and store the private key as the SNOWFLAKE_PRIVATE_KEY_RAW repo
-- secret. Rename the user freely; SNOWFLAKE_USER must match.
CREATE USER IF NOT EXISTS STREAMSNOW_DEPLOY_USER
  TYPE = SERVICE
  DEFAULT_ROLE = STREAMSNOW_DEPLOY_ROLE
  DEFAULT_WAREHOUSE = STREAMSNOW_WH
  RSA_PUBLIC_KEY = '<paste public key>';

-- 3. Grants -------------------------------------------------------------
USE ROLE SECURITYADMIN;
GRANT ROLE STREAMSNOW_DEPLOY_ROLE TO USER STREAMSNOW_DEPLOY_USER;
GRANT ROLE STREAMSNOW_DEPLOY_ROLE TO ROLE SYSADMIN;
GRANT ROLE STREAMSNOW_VIEWER_ROLE TO ROLE SYSADMIN;
-- So you can open the apps yourself: GRANT ROLE STREAMSNOW_VIEWER_ROLE TO USER <your_user>;
GRANT USAGE ON DATABASE STREAMSNOW_APPS TO ROLE STREAMSNOW_DEPLOY_ROLE;
GRANT USAGE ON SCHEMA STREAMSNOW_APPS.DASHBOARDS TO ROLE STREAMSNOW_DEPLOY_ROLE;
GRANT USAGE ON WAREHOUSE STREAMSNOW_WH TO ROLE STREAMSNOW_DEPLOY_ROLE;
GRANT USAGE ON DATABASE STREAMSNOW_APPS TO ROLE STREAMSNOW_VIEWER_ROLE;
GRANT USAGE ON SCHEMA STREAMSNOW_APPS.DASHBOARDS TO ROLE STREAMSNOW_VIEWER_ROLE;
GRANT USAGE ON WAREHOUSE STREAMSNOW_WH TO ROLE STREAMSNOW_VIEWER_ROLE;
GRANT CREATE STREAMLIT ON SCHEMA STREAMSNOW_APPS.DASHBOARDS TO ROLE STREAMSNOW_DEPLOY_ROLE;
GRANT CREATE STAGE ON SCHEMA STREAMSNOW_APPS.DASHBOARDS TO ROLE STREAMSNOW_DEPLOY_ROLE;

-- Data the apps read: governance database ANALYTICS_DB, allowed schemas only
-- (ANALYTICS, REPORTING). Only the CI role gets it: deployed apps run with
-- their owner's rights, so viewers need USAGE on the app, not SELECT on the data.
GRANT USAGE ON DATABASE ANALYTICS_DB TO ROLE STREAMSNOW_DEPLOY_ROLE;
GRANT USAGE ON SCHEMA ANALYTICS_DB.ANALYTICS TO ROLE STREAMSNOW_DEPLOY_ROLE;
GRANT SELECT ON ALL TABLES IN SCHEMA ANALYTICS_DB.ANALYTICS TO ROLE STREAMSNOW_DEPLOY_ROLE;
GRANT SELECT ON ALL VIEWS IN SCHEMA ANALYTICS_DB.ANALYTICS TO ROLE STREAMSNOW_DEPLOY_ROLE;
GRANT SELECT ON FUTURE TABLES IN SCHEMA ANALYTICS_DB.ANALYTICS TO ROLE STREAMSNOW_DEPLOY_ROLE;
GRANT SELECT ON FUTURE VIEWS IN SCHEMA ANALYTICS_DB.ANALYTICS TO ROLE STREAMSNOW_DEPLOY_ROLE;
GRANT USAGE ON SCHEMA ANALYTICS_DB.REPORTING TO ROLE STREAMSNOW_DEPLOY_ROLE;
GRANT SELECT ON ALL TABLES IN SCHEMA ANALYTICS_DB.REPORTING TO ROLE STREAMSNOW_DEPLOY_ROLE;
GRANT SELECT ON ALL VIEWS IN SCHEMA ANALYTICS_DB.REPORTING TO ROLE STREAMSNOW_DEPLOY_ROLE;
GRANT SELECT ON FUTURE TABLES IN SCHEMA ANALYTICS_DB.REPORTING TO ROLE STREAMSNOW_DEPLOY_ROLE;
GRANT SELECT ON FUTURE VIEWS IN SCHEMA ANALYTICS_DB.REPORTING TO ROLE STREAMSNOW_DEPLOY_ROLE;
-- Opt-in only: let the viewer role query this data directly (for example so
-- local preview can connect as the viewer role). Leave commented for least privilege:
--   GRANT USAGE ON DATABASE ANALYTICS_DB TO ROLE STREAMSNOW_VIEWER_ROLE;
--   GRANT USAGE ON SCHEMA ANALYTICS_DB.ANALYTICS TO ROLE STREAMSNOW_VIEWER_ROLE;
--   GRANT SELECT ON ALL TABLES IN SCHEMA ANALYTICS_DB.ANALYTICS TO ROLE STREAMSNOW_VIEWER_ROLE;
--   GRANT SELECT ON ALL VIEWS IN SCHEMA ANALYTICS_DB.ANALYTICS TO ROLE STREAMSNOW_VIEWER_ROLE;
--   GRANT SELECT ON FUTURE TABLES IN SCHEMA ANALYTICS_DB.ANALYTICS TO ROLE STREAMSNOW_VIEWER_ROLE;
--   GRANT SELECT ON FUTURE VIEWS IN SCHEMA ANALYTICS_DB.ANALYTICS TO ROLE STREAMSNOW_VIEWER_ROLE;
--   GRANT USAGE ON SCHEMA ANALYTICS_DB.REPORTING TO ROLE STREAMSNOW_VIEWER_ROLE;
--   GRANT SELECT ON ALL TABLES IN SCHEMA ANALYTICS_DB.REPORTING TO ROLE STREAMSNOW_VIEWER_ROLE;
--   GRANT SELECT ON ALL VIEWS IN SCHEMA ANALYTICS_DB.REPORTING TO ROLE STREAMSNOW_VIEWER_ROLE;
--   GRANT SELECT ON FUTURE TABLES IN SCHEMA ANALYTICS_DB.REPORTING TO ROLE STREAMSNOW_VIEWER_ROLE;
--   GRANT SELECT ON FUTURE VIEWS IN SCHEMA ANALYTICS_DB.REPORTING TO ROLE STREAMSNOW_VIEWER_ROLE;
-- If ANALYTICS_DB is a SHARED database (a Marketplace or data-share import,
-- e.g. SNOWFLAKE_SAMPLE_DATA), the grants above fail; use this instead,
-- as ACCOUNTADMIN (it covers the whole share, not just the allowed schemas):
--   GRANT IMPORTED PRIVILEGES ON DATABASE ANALYTICS_DB TO ROLE STREAMSNOW_DEPLOY_ROLE;

-- 4. Account-level objects -----------------------------------------------
USE ROLE ACCOUNTADMIN;
-- PyPI access for the container image build. Uses Snowflake's managed
-- network rule for PyPI. If your account prefers an artifact repository,
-- skip this: configuring both disables the EAI.
-- (Snowflake has no IF NOT EXISTS for this statement: skip it on a re-run.)
CREATE EXTERNAL ACCESS INTEGRATION PYPI_ACCESS_INTEGRATION
  ALLOWED_NETWORK_RULES = (snowflake.external_access.pypi_rule)
  ENABLED = TRUE;
-- Without the managed rule, create your own and list it above instead:
--   CREATE NETWORK RULE STREAMSNOW_APPS.DASHBOARDS.PYPI_NETWORK_RULE MODE = EGRESS TYPE = HOST_PORT
--     VALUE_LIST = ('pypi.org', 'files.pythonhosted.org');
GRANT USAGE ON INTEGRATION PYPI_ACCESS_INTEGRATION TO ROLE STREAMSNOW_DEPLOY_ROLE;
-- SYSTEM_COMPUTE_POOL_CPU is pre-provisioned by Snowflake in every account (USAGE
-- goes to PUBLIC by default), so it is not created here. The explicit
-- grant keeps deploys working if PUBLIC's USAGE is ever revoked.
GRANT USAGE ON COMPUTE POOL SYSTEM_COMPUTE_POOL_CPU TO ROLE STREAMSNOW_DEPLOY_ROLE;

-- 5. Deploy-source objects, created by the CI role that will own them ---------
USE ROLE STREAMSNOW_DEPLOY_ROLE;
CREATE STAGE IF NOT EXISTS STREAMSNOW_APPS.DASHBOARDS.STREAMSNOW_CODE_STAGE
  COMMENT = 'StreamSnow app source, SHA-versioned per deploy';
